//! 重复引擎差分对拍 —— 期望值由 **v1 Python 源码原样摘出的独立脚本** 生成
//! (见 v1 `backend/app/crud.py:123-319`,脚本只依赖标准库)。
//!
//! 生成方式(v1 仓库侧):
//! `python v1_repeat.py < cases.json > v1_expected.jsonl`,再把结果逐行嵌入
//! 下方 `EXPECTED`。28 个用例覆盖:daily/weekday/weekly/monthly/yearly 全规则、
//! 上限 50、缺日跳月、2/29、custom 四型 + interval 夹紧 + 严格边界 + 非法 JSON。
//! 改 `repeat.rs` 的日期算术后必须重跑对拍,保证与 v1 语义零漂移。

use chrono::{DateTime, Utc};
use pomoflow_core::model::Repeat;
use pomoflow_core::repeat::compute_repeat_dates;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct Case {
    rule: String,
    due: Option<String>,
    #[serde(default)]
    config: Option<String>,
    dates: Vec<String>,
}

fn rule_of(s: &str) -> Repeat {
    match s {
        "daily" => Repeat::Daily,
        "weekday" => Repeat::Weekdays,
        "weekly" => Repeat::Weekly,
        "monthly" => Repeat::Monthly,
        "yearly" => Repeat::Yearly,
        "custom" => Repeat::Custom,
        _ => Repeat::None,
    }
}

#[test]
fn parity_with_v1_python() {
    for line in EXPECTED.lines().filter(|l| !l.trim().is_empty()) {
        let case: Case = serde_json::from_str(line).expect("嵌入的期望 JSON 非法");
        let due = case.due.as_deref().and_then(|s| {
            chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M")
                .ok()
                .map(|n| DateTime::<Utc>::from_naive_utc_and_offset(n, Utc))
        });
        let out: Vec<String> = compute_repeat_dates(
            rule_of(&case.rule),
            due,
            case.config.as_deref(),
            // v1 期望值是 naive 墙钟串;tz=0 下墙钟 == UTC,重写后的墙钟算术
            // 与旧 UTC 算术等价,期望值原样成立
            0,
        )
        .iter()
        .map(|d| d.format("%Y-%m-%dT%H:%M").to_string())
        .collect();
        assert_eq!(
            out, case.dates,
            "rule={} due={:?} config={:?}",
            case.rule, case.due, case.config
        );
    }
}

